// QUANTUM kit common helpers.
// Starfield on the view sphere: dir must be normalised. density 0..1, returns radiance.
vec3 Q_stars(vec3 dir, float density) {
  vec3 col = vec3(0.0);
  for (int l = 0; l < 3; l++) {
    float sc = 60.0 + float(l) * 90.0;
    vec3 p = dir * sc;
    vec3 c = floor(p);
    vec3 h = h33(c + float(l) * 17.0);
    if (h.x < density * (0.35 - float(l) * 0.08)) {
      vec3 sp = c + 0.2 + 0.6 * h;
      float d = length(p - sp);
      float br = pow(h.y, 6.0) * 3.0 + 0.2;
      float tw = 0.75 + 0.25 * lsin(float(1 + int(h.z * 3.0)), h.x * 7.0);
      col += bb(3000.0 + 9000.0 * h.z) * br * tw * exp(-d * d * (18.0 + float(l) * 10.0));
    }
  }
  return col;
}
// 2D starfield in uv space with occasional diffraction spikes.
vec3 Q_stars2(vec2 uv, float density, float spikes) {
  vec3 col = vec3(0.0);
  for (int l = 0; l < 3; l++) {
    float sc = 22.0 + float(l) * 30.0;
    vec2 p = uv * sc + float(l) * 13.1;
    vec2 c = floor(p); vec3 h = h33(vec3(c, float(l) + 4.0));
    if (h.x < density * (0.5 - float(l) * 0.12)) {
      vec2 d = p - c - 0.2 - 0.6 * h.xy;
      float br = pow(h.z, 5.0) * 2.5 + 0.12;
      float tw = 0.8 + 0.2 * lsin(float(1 + int(h.y * 3.0)), h.z * 5.0);
      float core = exp(-dot(d, d) * 60.0);
      float spk = spikes * br * (exp(-abs(d.x) * 60.0) * exp(-abs(d.y) * 4.0) + exp(-abs(d.y) * 60.0) * exp(-abs(d.x) * 4.0)) * step(0.85, h.z);
      col += bb(2800.0 + 9000.0 * fract(h.y * 7.0)) * (core * br + spk * 0.25) * tw;
    }
  }
  return col;
}
// Accretion-style colour ramp from temperature 0..1 using the palette.
vec3 Q_heat(float t) { t = sat(t); return mix(mix(u_a2 * 0.3, u_a0, sat(t * 1.8)), mix(u_a1, u_ink, sat(t * 2.0 - 1.0)), sat(t * 1.6 - 0.5)); }
// Noise on a torus: periodic with period 1 in both t.x and t.y. r = radii (feature density).
float Q_tnoise(vec2 t, vec2 r, int oct) {
  float s = 0.0, a = 0.5; vec2 rr = r;
  for (int i = 0; i < 6; i++) {
    if (i >= oct) break;
    vec4 p = vec4(rr.x * cos(TAU * t.x), rr.x * sin(TAU * t.x), rr.y * cos(TAU * t.y), rr.y * sin(TAU * t.y));
    s += a * snoise(p + vec4(M_seedOff(), float(i) * 3.1, 1.7));
    rr *= 2.0; a *= 0.5;
  }
  return s;
}

files.styles/bubble-chamber.glsl:
// Bubble Chamber — charged particles spiral through a magnetic field, bleeding energy into tightening curls; pairs fork in V's.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec3 col = vec3(0.0); float cover = 0.0;
  float px = aa();
  // chamber background: faint liquid texture
  float bgT = lfbm(uv * 3.0, 3, 1.0, 0.15) * 0.5 + 0.5;
  col += u_a2 * 0.07 * bgT * p_liquid;
  for (int i = 0; i < 24; i++) {
    if (i >= p_tracks) break;
    float fi = float(i);
    vec3 h = h33(vec3(fi, 2.0, 7.0));
    // event timing: each track appears, grows, lingers, fades (loop-periodic)
    float t = fract(u_p * float(p_rate) + h.x);
    float grow = smoothstep(0.0, 0.25, t);
    float fade = 1.0 - smoothstep(0.7, 1.0, t);
    if (fade <= 0.0) continue;
    float charge = h.y < 0.5 ? 1.0 : -1.0;
    // entry: particles stream in from the left edge; some are created in the chamber (pair production)
    bool pair = h.z < p_pairs;
    vec2 start = pair ? (h33(vec3(fi, 5.0, 1.0)).xy - 0.5) * A * 1.4 : vec2(-A.x - 0.05, (h.z - 0.5) * A.y * 1.6);
    float dir0 = pair ? TAU * h.x : (h.y - 0.5) * 0.6;
    float R0 = (0.15 + 0.9 * pow(fract(h.x * 13.0), 2.0)) * p_momentum;    // initial radius (momentum)
    float b = 0.06 + 0.25 * fract(h.z * 7.0) * p_energyLoss;                // spiral tightening
    // log-spiral centre
    vec2 nrm = vec2(-sin(dir0), cos(dir0)) * charge;
    vec2 ctr = start + nrm * R0;
    vec2 q = uv - ctr;
    float r = length(q);
    float th = atan(q.y, q.x);
    float th0 = atan(start.y - ctr.y, start.x - ctr.x);
    // angle travelled along the spiral (in the direction of motion)
    float dth = charge * (th0 - th);
    dth = mod(dth, TAU);
    float best = 1e9; float bestS = 0.0;
    float turns = 1.0 + 4.0 * p_energyLoss;
    for (int k = 0; k < 6; k++) {
      float tk = dth + TAU * float(k);
      if (tk > turns * TAU) break;
      float rk = R0 * exp(-b * tk);
      float d = abs(r - rk);
      if (d < best) { best = d; bestS = tk / (turns * TAU); }
    }
    float visible = step(bestS, grow);
    // bubbles: dotted along the track, denser as the particle slows
    float s = bestS * 300.0 * p_bubbleDensity;
    float bub = mix(0.35, 1.0, step(0.35, h11(floor(s) + fi * 1000.0)));
    float trackW = max(0.0018 * p_width * (1.0 + bestS), px * 0.8);
    float tr = (1.0 - smoothstep(trackW, trackW + px, best)) * visible * bub;
    vec3 tc = charge > 0.0 ? u_a0 : u_a1;
    if (p_mono) tc = u_ink;
    col += tc * tr * fade * 1.2 + tc * glow2(best, 0.004) * (0.08 * p_glow + 0.04) * visible * fade;
    cover = max(cover, tr * fade);
    // pair vertex marker
    if (pair) col += u_ink * exp(-dot(uv - start, uv - start) * 30000.0) * grow * fade;
  }
  // beam flash lines (entry markers)
  col = aces(col * 1.2);
  return vec4(col, max(cover, max(max(col.r, col.g), col.b)));
}

files.styles/cosmic-web.glsl:
// Cosmic Web — an infinite flight into the dark-matter scaffold: filaments, clusters and galaxies at every scale.
float CW_web(vec2 p, float lvl) {
  vec3 v = lvoro(p, 0.95, 1.0, 0.15);
  float e = v.y - v.x;
  float fil = exp(-e * e * 220.0 / (p_thickness * p_thickness)) * (0.4 + 0.6 * step(0.35, fract(v.z * 13.0)));
  float node = exp(-v.x * v.x * 30.0) * step(0.5, fract(v.z * 7.0 + lvl)) * p_nodes;
  return fil * 0.7 + node * 1.4;
}
vec4 motif(vec2 uv, vec2 fc) {
  // log-periodic zoom: four octaves blended so the loop closes after one doubling
  float z = u_p * float(p_zoomSpeed);
  vec3 col = vec3(0.0);
  vec2 q = rot(p_twist * 0.35 * lsin(1.0, 0.0)) * uv;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    float lvl = fi - fract(z);
    float sc = pow(2.0, lvl) * 0.9 * p_scale;
    float w = sat(1.0 - abs(lvl - 2.0) / (1.5 + 1.5 * p_depth));   // fade in from far, out when too close
    w = w * w * (3.0 - 2.0 * w);
    float oct = mod(floor(z) + fi, float(p_zoomSpeed) * 4.0 > 0.0 ? float(p_zoomSpeed) : 1.0); // identity per octave, periodic over the loop
    vec2 pp = q * sc + vec2(h11(oct + 1.0), h11(oct + 9.0)) * 50.0;
    float web = CW_web(pp, oct);
    float gas = lfbm(pp * 0.5, 3, 1.0, 0.2) * 0.5 + 0.5;
    vec3 c = mix(u_a1, u_a0, sat(web * 0.8)) * web + u_a1 * pow(gas, 4.0) * 0.18 * p_gas;
    // galaxies: sparkles concentrated along filaments
    vec2 gp = pp * 6.0; vec2 gn = floor(gp); vec3 gh = h33(vec3(gn, oct));
    float gd = length(gp - gn - 0.2 - 0.6 * gh.xy);
    c += mix(u_ink, u_a1, gh.z) * exp(-gd * gd * 90.0) * step(1.0 - web * 0.9 * p_galaxies, gh.z) * 1.5;
    col += c * w * 0.55;
  }
  col = aces(col * 1.3 * p_brightness);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/double-slit.glsl:
// Double Slit — wavefronts pass two slits and interfere; single particles land one by one and the fringes build.
float DS_I(float y, float d, float w, float k, bool which) {
  float beta = k * w * y * 0.5; float env = beta == 0.0 ? 1.0 : pow(sin(beta) / beta, 2.0);
  float fr = which ? 0.5 : pow(cos(k * d * y * 0.5), 2.0);
  return env * fr;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float bx = -A.x * 0.15;              // barrier x
  float sx = A.x * 0.72;               // screen x
  float d = 0.12 * p_separation, w = 0.02 * p_slitWidth;
  float k = 90.0 / p_wavelength;
  vec3 col = vec3(0.0); float cover = 0.0;
  float cyc = fract(u_p * float(p_cycles));
  bool which = p_detector;
  // source waves (left of the barrier): plane waves moving right
  if (uv.x < bx) {
    float ph = uv.x * k * 0.35 - TAU * u_p * float(p_waveSpeed) * 4.0;
    float wv = 0.5 + 0.5 * cos(ph);
    col += u_a2 * wv * 0.35 * p_waves * smoothstep(-A.x, bx, uv.x);
  } else if (uv.x < sx) {
    // two-source interference
    vec2 s1 = vec2(bx, d * 0.5), s2 = vec2(bx, -d * 0.5);
    float r1 = length(uv - s1), r2 = length(uv - s2);
    float ph = -TAU * u_p * float(p_waveSpeed) * 4.0;
    vec2 a1 = vec2(cos(r1 * k * 0.35 + ph), sin(r1 * k * 0.35 + ph)) / sqrt(r1 + 0.02);
    vec2 a2 = vec2(cos(r2 * k * 0.35 + ph), sin(r2 * k * 0.35 + ph)) / sqrt(r2 + 0.02);
    vec2 a = which ? a1 : a1 + a2;
    float I = which ? (dot(a1, a1) + dot(a2, a2)) * 0.5 : dot(a, a) * 0.25;
    float crest = which ? max(0.5 + 0.5 * a1.x * sqrt(r1 + 0.02), 0.5 + 0.5 * a2.x * sqrt(r2 + 0.02)) : 0.5 + 0.5 * a.x * 0.5 * sqrt(min(r1, r2) + 0.02);
    col += mix(u_a2, u_a0, sat(I * 0.8)) * (I * 0.12 + crest * 0.25) * p_waves;
  }
  // barrier with slits
  float bar = step(abs(uv.x - bx), 0.006) * (1.0 - step(abs(abs(uv.y) - d * 0.5), w * 0.5));
  col = mix(col, u_ink * 0.7, bar); cover = max(cover, bar);
  // screen + accumulated hits
  float scr = step(abs(uv.x - sx), 0.004);
  col = mix(col, u_ink * 0.25, scr);
  float hits = 0.0;
  if (uv.x > sx - 0.04) {
    float count = floor(pow(smoothstep(0.02, 0.85, cyc), 1.3) * 900.0 * p_rate);
    float fade = 1.0 - smoothstep(0.9, 1.0, cyc);
    // hits live on a vertical strip right of the screen; test candidates in this pixel's row band
    float band = floor((uv.y + A.y) / (2.0 * A.y) * 90.0);
    for (int i = 0; i < 24; i++) {
      float id = band * 24.0 + float(i);
      vec3 h = h33(vec3(id, 5.0, 2.0));
      float order = h.z * 900.0;
      if (order > count) continue;
      float y = (band + h.x) / 90.0 * 2.0 * A.y - A.y;
      // acceptance by the interference distribution (rejection sampling)
      if (h.y > DS_I(y / (sx - bx) * 0.6, d, w, k, which)) continue;
      vec2 hp = vec2(sx + 0.01 + h.x * 0.06 * p_spread, y);
      float dd = length(uv - hp);
      float age = sat((count - order) / 40.0);
      hits += (1.0 - smoothstep(0.0025, 0.0025 + aa(), dd)) * fade + glow2(dd, 0.004) * (1.0 - age) * 0.6 * fade;
    }
  }
  col += mix(u_a1, u_ink, 0.3) * hits * 1.3;
  cover = max(cover, sat(hits));
  // expected distribution curve on the screen
  float I = DS_I(uv.y / (sx - bx) * 0.6, d, w, k, which);
  col += u_a0 * line(abs(uv.x - (sx - 0.02 - I * 0.12)), 0.002) * p_curve * step(uv.x, sx);
  col = aces(col * 1.2);
  return vec4(col, max(cover, max(max(col.r, col.g), col.b)));
}

files.styles/entanglement.glsl:
// Entanglement — pairs fly apart from a source bound by a shared thread; measure one and both states snap, always opposite.
vec3 EN_bloch(vec2 q, float R, vec3 s, vec3 c) {
  // simple Bloch sphere: outline, equator, state arrow
  float d = abs(length(q) - R);
  vec3 col = u_ink * line(d, 0.003) * 0.6;
  vec2 eq = q / vec2(1.0, 0.3);
  col += u_ink * line(abs(length(eq) - R), 0.003) * 0.25;
  vec2 tip = vec2(s.x, s.z * 0.95 + s.y * 0.3) * R;
  float da = sdSeg(q, vec2(0.0), tip);
  col += c * (line(da, 0.006) + exp(-length(q - tip) * length(q - tip) * 4000.0) * 1.5);
  return col;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  float D = A.x * 0.72;              // detector distance
  vec3 col = vec3(0.0);
  int NP = p_pairs;
  float lastMeasure = -1.0; float outcome = 0.0; float measT = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= NP) break;
    float fi = float(i);
    float t = fract(u_p * float(p_rate) + fi / float(NP));
    float x = t * D * 1.15;
    float yOff = (h11(fi + 3.0) - 0.5) * 0.25 * p_spread;
    vec2 pa = vec2(x, yOff * t), pb = vec2(-x, -yOff * t);
    float measured = step(D, x);
    float res = step(0.5, h11(fi * 7.0 + mod(floor(u_p * float(p_rate) + fi / float(NP)), float(p_rate)) * 13.0));
    // superposed spin: fuzzy, rotating; after measurement: definite and opposite
    float spin = TAU * (u_p * float(p_rate) * 3.0 + fi * 0.37);
    vec3 cA = measured > 0.5 ? (res > 0.5 ? u_a0 : u_a1) : mix(u_a0, u_a1, 0.5 + 0.5 * sin(spin));
    vec3 cB = measured > 0.5 ? (res > 0.5 ? u_a1 : u_a0) : mix(u_a1, u_a0, 0.5 + 0.5 * sin(spin));
    float fadeOut = 1.0 - smoothstep(0.92, 1.0, t);
    for (int s = 0; s < 2; s++) {
      vec2 pp = s == 0 ? pa : pb;
      float d = length(uv - pp);
      float r = 0.012 * p_size;
      float halo = measured > 0.5 ? 0.0 : (0.5 + 0.5 * sin(spin * 2.0)) * p_superposition;
      col += (s == 0 ? cA : cB) * ((1.0 - smoothstep(r, r + aa(), d)) * 1.2 + glow2(d, r * (1.5 + 2.0 * halo)) * 0.35 * p_glow) * fadeOut;
    }
    // entanglement thread: a standing wave strung between the pair
    if (measured < 0.5) {
      vec2 ab = pa - pb; float L = length(ab); vec2 dir = ab / max(L, 1e-4), nn = vec2(-dir.y, dir.x);
      float s = dot(uv - pb, dir), n = dot(uv - pb, nn);
      if (s > 0.0 && s < L) {
        float wave = sin(s / max(L, 1e-3) * PI * float(p_threadModes)) * 0.02 * p_thread * sin(spin);
        float dd = abs(n - wave);
        col += mix(u_a2, u_ink, 0.3) * (line(dd, 0.002) * 0.7 + glow2(dd, 0.006) * 0.15) * p_thread;
      }
    } else if (t > lastMeasure) { lastMeasure = t; outcome = res; measT = (x - D) / (D * 0.15); }
  }
  // detectors + Bloch spheres showing the most recent correlated outcome
  for (int s = 0; s < 2; s++) {
    float sg = s == 0 ? 1.0 : -1.0;
    vec2 dp = vec2(sg * D, 0.0);
    float det = sdBox(uv - dp, vec2(0.006, A.y * 0.55));
    col += u_ink * 0.35 * (1.0 - smoothstep(0.0, aa(), det));
    vec2 bq = uv - vec2(sg * (D + A.x * 0.13), -A.y * 0.55);
    float up = lastMeasure >= 0.0 ? (s == 0 ? outcome : 1.0 - outcome) : 0.5;
    vec3 st = normalize(vec3(0.0, 0.0, up > 0.5 ? 1.0 : -1.0) + vec3(0.001));
    col += EN_bloch(bq, 0.07, st, up > 0.5 ? u_a0 : u_a1) * p_bloch;
  }
  // source
  col += u_ink * exp(-dot(uv, uv) * 3000.0) * 1.5 + u_a2 * glow2(length(uv), 0.03) * 0.3;
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/event-horizon-scene.glsl:
// Event Horizon (pass 1) — photon paths bent around a black hole; accretion disk with Doppler beaming, lensed starfield.
vec4 motif(vec2 uv, vec2 fc) {
  float incl = mix(0.04, 0.55, p_tilt);
  float orbit = 0.25 * lsin(1.0, 0.0) * 0.3;
  vec3 ro = vec3(sin(orbit) * 22.0, 22.0 * sin(incl), -22.0 * cos(incl) * cos(orbit));
  vec3 fw = normalize(-ro), rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw)), up = cross(fw, rt);
  vec3 rd = normalize(fw * 2.4 * p_fov + uv.x * rt + uv.y * up);
  vec3 pos = ro, vel = rd;
  float rs = 1.0;                         // Schwarzschild radius
  float rin = 3.0 * rs * p_innerEdge, rout = rin + 6.0 * p_diskSize;
  vec3 col = vec3(0.0); float trans = 1.0; float captured = 0.0; float ringGlow = 0.0;
  float dt = 0.2;
  int steps = 44 + int(76.0 * p_quality);
  for (int i = 0; i < 120; i++) {
    if (i >= steps) break;
    float r = length(pos);
    if (r < rs) { captured = 1.0; break; }
    if (r > 40.0 && dot(pos, vel) > 0.0) break;
    // null geodesic in Schwarzschild, Binet-style acceleration: a = -1.5 rs h^2 / r^5 * pos
    vec3 hv = cross(pos, vel); float h2 = dot(hv, hv);
    vec3 acc = -1.5 * rs * h2 * pos / pow(r, 5.0) * p_lensing;
    float stepLen = dt * clamp(r * 0.4, 0.08, 3.0);
    vec3 np = pos + vel * stepLen; vel = normalize(vel + acc * stepLen);
    ringGlow += exp(-pow((r - 1.5 * rs) * 6.0, 2.0)) * stepLen * 0.25;
    // disk crossing (y = 0 plane)
    if (pos.y * np.y < 0.0) {
      float t = pos.y / (pos.y - np.y);
      vec3 hp = mix(pos, np, t);
      float rr = length(hp.xz);
      if (rr > rin && rr < rout) {
        float ang = atan(hp.z, hp.x);
        float x = (rr - rin) / (rout - rin);
        // spiral inflow arms rotating rigidly + loop turbulence
        float arms = 0.5 + 0.5 * sin(ang * 3.0 + log(rr) * 9.0 * p_spiral - TAU * u_p * float(p_rotation) * 3.0);
        float turb = lfbm(vec2(ang * 3.0 / TAU * 8.0, log(rr) * 6.0), 3, float(p_rotation), 0.35) * 0.5 + 0.5;
        float dens = pow(1.0 - x, 1.2) * smoothstep(0.0, 0.04, x) * mix(1.0, turb * 1.6, p_turbulence) * mix(1.0, 0.55 + arms, 0.6 * p_turbulence);
        // Doppler beaming: disk rotates, approaching side brighter
        vec3 v = normalize(vec3(-hp.z, 0.0, hp.x)) * sqrt(0.5 * rs / rr);
        float beam = pow(sat(1.0 + dot(v, -normalize(vel)) * 2.2 * p_doppler), 3.0);
        float temp = pow(rin / rr, 0.75);
        vec3 c = Q_heat(temp * 0.9 + 0.1 * turb) * dens * beam * 0.9 * p_brightness;
        col += c * trans;
        trans *= 1.0 - sat(dens * 0.5);
      }
    }
    pos = np;
    if (trans < 0.02) break;
  }
  if (captured < 0.5) col += Q_stars(normalize(vel), p_stars) * trans * 1.2;
  col += (u_a1 * 0.35 + u_ink * 0.15) * ringGlow * p_photonRing * trans * (1.0 - 0.85 * captured);
  return vec4(col, 1.0);
}

files.styles/feynman-paths.glsl:
// Feynman Paths — every path from source to detector at once: phases swirl, and the classical path emerges where they agree.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 A = M_asp() * 0.5;
  vec2 a = vec2(-A.x * 0.8, 0.0), b = vec2(A.x * 0.8, 0.0);
  float L = b.x - a.x;
  float s = (uv.x - a.x) / L;
  vec3 col = vec3(0.0); float cover = 0.0;
  vec2 sumA = vec2(0.0);
  float omega = TAU * u_p * float(p_speed);
  // cull: no path strays further than the sum of its mode amplitudes
  float yMax = 0.69 * p_spread + 0.06;
  if (s > 0.0 && s < 1.0 && abs(uv.y) < yMax) {
    for (int i = 0; i < 64; i++) {
      if (i >= p_paths) break;
      float fi = float(i);
      // path = classical straight line + Fourier modes with fixed endpoints
      float y = 0.0, dy = 0.0, action = 0.0;
      float spread = p_spread * (0.3 + 1.2 * pow(h11(fi + 1.0), 2.0));
      for (int k = 1; k <= 5; k++) {
        if (k > p_modes) break;
        float fk = float(k);
        float ak = (h11(fi * 7.0 + fk) - 0.5) * 0.35 * spread / fk * (1.0 + 0.15 * lsin(1.0, h11(fi + fk * 3.0)));
        y += ak * sin(PI * fk * s);
        dy += ak * PI * fk * cos(PI * fk * s) / L;
        action += ak * ak * fk * fk;
      }
      float phase = action * 60.0 * p_hbar - omega;
      vec3 c = mix(mix(u_a0, u_a1, 0.5 + 0.5 * cos(phase)), u_a2, 0.5 + 0.5 * sin(phase) * 0.5);
      float d = abs(uv.y - y) / sqrt(1.0 + dy * dy);
      float wgt = 1.0 / float(p_paths) * 30.0;
      float coherence = exp(-action * 20.0 * p_hbar);
      col += c * (line(d, 0.0018 * p_lineWidth) * (0.25 + 0.75 * coherence) + glow2(d, 0.004) * 0.05 * p_glow) * wgt * 0.3;
      cover = max(cover, line(d, 0.0018) * 0.5);
    }
  }
  // the classical path emerges (stationary action)
  float dcl = abs(uv.y);
  col += mix(u_ink, u_a2, 0.3) * line(dcl, 0.003) * p_classical * step(0.0, s) * step(s, 1.0) + u_a2 * glow2(dcl, 0.01) * 0.2 * p_classical * step(0.0, s) * step(s, 1.0);
  // phasor sum: arrows chained head to tail at the bottom (Feynman's little arrows)
  vec2 o = vec2(-A.x * 0.55, -A.y * 0.72);
  vec2 cur = o; float arrows = 0.0;
  for (int i = 0; i < 24; i++) {
    if (i >= p_paths) break;
    float fi = float(i); float action = 0.0;
    float spread = p_spread * (0.3 + 1.2 * pow(h11(fi + 1.0), 2.0));
    for (int k = 1; k <= 5; k++) { if (k > p_modes) break; float fk = float(k); float ak = (h11(fi * 7.0 + fk) - 0.5) * 0.35 * spread / fk * (1.0 + 0.15 * lsin(1.0, h11(fi + fk * 3.0))); action += ak * ak * fk * fk; }
    float phase = action * 60.0 * p_hbar - omega;
    vec2 nx = cur + vec2(cos(phase), sin(phase)) * 0.028 * p_arrows;
    arrows += line(sdSeg(uv, cur, nx), 0.0025);
    cur = nx;
  }
  col += u_a1 * arrows * 0.9 * step(0.001, p_arrows);
  col += u_ink * line(sdSeg(uv, o, cur), 0.003) * step(0.001, p_arrows);
  // source + detector
  col += u_ink * (exp(-dot(uv - a, uv - a) * 4000.0) + exp(-dot(uv - b, uv - b) * 4000.0)) * 1.5;
  col = aces(col * 1.2);
  return vec4(col, max(cover, max(max(col.r, col.g), col.b)));
}

files.styles/galaxy-collision.glsl:
// Galaxy Collision — two spirals swing past each other; tides pull their arms into long luminous tails and bridges.
vec3 GC_galaxy(vec2 q, float spin, float arms, float tilt, vec3 tint, float seedOff) {
  q.y /= tilt;
  float r = length(q), a = atan(q.y, q.x);
  float spiral = 0.5 + 0.5 * cos(arms * (a - log(r + 1e-3) * 2.6 * p_winding) - spin);
  float disk = exp(-r * 9.0);
  float bulge = exp(-r * r * 900.0) * 1.6 + exp(-r * 28.0) * 0.6;
  float clumps = pow(sat(lfbm(q * 14.0 + seedOff, 4, 1.0, 0.25) + 0.3), 3.0);
  float dust = 1.0 - 0.55 * p_dust * smoothstep(0.4, 0.9, spiral) * exp(-r * 6.0) * sat(lfbm(q * 30.0 + seedOff, 3, 1.0, 0.2) + 0.6);
  vec3 armC = mix(tint, u_a2, 0.5) * pow(spiral, 2.0) * disk * (0.6 + 1.6 * clumps);
  return (armC + mix(u_a1, u_ink, 0.5) * bulge) * dust;
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 q = uv / p_scale;
  // encounter orbit: periodic ellipse in the loop, closest approach twice per cycle
  float ph = TAU * u_p * float(p_orbits);
  vec2 rel = vec2(cos(ph) * 0.34 * p_separation, sin(ph) * 0.14 * p_separation);
  float close = exp(-length(rel) * 5.0);
  vec2 c1 = rel * 0.5, c2 = -rel * 0.5;
  // tidal warp: stretch each galaxy toward the companion, strongest at close approach
  vec2 d12 = normalize(c2 - c1 + 1e-4);
  vec2 q1 = q - c1, q2 = q - c2;
  float tide = p_tides * (0.3 + close);
  q1 -= d12 * dot(q1, d12) * tide * 0.35 * smoothstep(0.0, 0.2, length(q1));
  q2 += d12 * dot(q2, -d12) * tide * 0.35 * smoothstep(0.0, 0.2, length(q2));
  float spin = TAU * u_p * float(p_orbits) * 2.0;
  vec3 col = GC_galaxy(q1, spin, 2.0, 0.55, u_a0, 0.0) + GC_galaxy(rot(0.8) * q2, -spin * 0.5, 2.0, 0.7, u_a2, 9.0) * 0.9;
  // tidal tails: long curved streams trailing each galaxy, plus the bridge between them
  for (int g = 0; g < 2; g++) {
    vec2 c = g == 0 ? c1 : c2;
    vec2 away = g == 0 ? -d12 : d12;
    vec2 perp = vec2(-away.y, away.x) * (g == 0 ? 1.0 : -1.0);
    vec2 dq = q - c;
    float s = dot(dq, away);
    float curve = 0.9 * s * s * p_tailCurve;
    float n = dot(dq, perp) - curve;
    float len = 0.7 * p_tails * (0.4 + close);
    float tail = exp(-n * n / pow(0.02 + s * 0.05, 2.0)) * smoothstep(0.0, 0.08, s) * exp(-s / max(len, 0.01) * 2.0);
    float knots = pow(sat(lfbm(vec2(s * 12.0, n * 30.0) + float(g) * 5.0, 4, 1.0, 0.25) + 0.4), 2.0);
    col += mix(u_a2, u_ink, 0.3) * tail * (0.4 + knots) * 0.8;
  }
  float b = abs(dot(q - c1, vec2(-d12.y, d12.x)));
  float along = dot(q - c1, d12) / max(length(c2 - c1), 1e-3);
  col += u_a2 * exp(-b * b * 800.0) * step(0.0, along) * step(along, 1.0) * close * 0.6 * p_tails;
  // starburst knots triggered by the encounter
  col += u_a1 * close * p_starburst * pow(sat(lfbm(q * 20.0, 3, 1.0, 0.2) + 0.1), 6.0) * exp(-min(length(q1), length(q2)) * 8.0) * 3.0;
  col += Q_stars2(uv, p_stars, 0.4) * 0.6;
  col = aces(col * 1.3);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/gravitational-wave.glsl:
// Gravitational Wave — two black holes spiral in and merge; the chirp ripples outward across a spacetime grid.
vec4 motif(vec2 uv, vec2 fc) {
  float ncyc = safeCycles(float(p_cycles)); float cyc = ncyc < 1.0 ? 0.45 : fract(u_p * ncyc);
  // inspiral: separation shrinks, orbital phase accelerates (chirp), merger at tm
  float tm = 0.72;
  float tau = max(tm - cyc, 0.0) / tm;           // 1 -> 0
  float sep = 0.16 * p_separation * pow(tau, 0.25);
  float orb = -18.0 * pow(tau, 0.625) * p_chirp;   // orbital phase
  float merged = step(tm, cyc);
  float fadeIn = smoothstep(0.0, 0.08, cyc), fadeOut = 1.0 - smoothstep(0.9, 1.0, cyc);
  // camera tilt: project the plane
  float tilt = 0.25 + 0.6 * p_tilt;
  vec2 w = vec2(uv.x, uv.y / tilt);
  float r = length(w);
  float phi = atan(w.y, w.x);
  // retarded time: wave at radius r was emitted at cyc - r / c
  float c = 0.9 * p_speed;
  float tr = cyc - r / c;
  tr = tr < 0.0 ? tr + 1.0 : tr;
  float taur = sat(max(tm - tr, 0.0) / tm);
  float orbr = -18.0 * pow(taur, 0.625) * p_chirp;
  float ampEmit = tr < tm ? pow(1.0 - taur, 1.5) : exp(-(tr - tm) * 30.0);   // grows toward merger, ringdown after
  float ringF = tr >= tm ? sin((tr - tm) * 180.0) : 1.0;
  float h = ampEmit * (tr < tm ? cos(2.0 * (phi - orbr)) : ringF * cos(2.0 * phi)) / (1.0 + r * 6.0);
  h *= p_amplitude;
  // gravity wells
  vec2 b1 = vec2(cos(orb), sin(orb)) * sep, b2 = -b1;
  float m = merged > 0.5 ? 0.0 : 1.0;
  float well = (m * (0.012 / (length(w - b1) + 0.03) + 0.012 / (length(w - b2) + 0.03)) + (1.0 - m) * 0.024 / (r + 0.035)) * p_well * fadeIn * fadeOut;
  // displaced grid
  float N = 8.0 * p_gridDensity;
  vec2 g = w * N + vec2(0.0, (h * 0.8 - well * 3.0) * N);
  vec2 gf = abs(fract(g) - 0.5) / N;
  float lw = 0.0012;
  float grid = max(line(gf.x * tilt, lw), line(gf.y * tilt, lw));
  float fog = exp(-r * 1.2);
  vec3 col = mix(u_a0 * 0.45, mix(u_a0, u_a1, step(0.0, h)) * 1.4, sat(abs(h) * 6.0)) * grid * (0.25 + 0.75 * fog);
  col += mix(u_a0, u_a1, step(0.0, h)) * abs(h) * 0.9 * p_strain * fog;
  // black holes: shadows with lensing rings
  for (int i = 0; i < 2; i++) {
    if (merged > 0.5 && i == 1) break;
    vec2 bp = merged > 0.5 ? vec2(0.0) : (i == 0 ? b1 : b2);
    float rb = merged > 0.5 ? 0.028 : 0.02;
    float d = length(w - bp);
    col = mix(col, u_bg * 0.0, (1.0 - smoothstep(rb * 0.9, rb, d)) * fadeIn * fadeOut);
    col += mix(u_a1, u_ink, 0.5) * exp(-pow((d - rb * 1.35) * 90.0, 2.0)) * fadeIn * fadeOut * 1.2;
  }
  // merger flash (limited)
  float fl = exp(-max(cyc - tm, 0.0) * 40.0) * step(tm, cyc);
  col += mix(u_ink, u_a1, 0.3) * flashAmt(fl) * p_flash * exp(-r * 5.0) * 1.5;
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/nebula-genesis.glsl:
// Nebula Genesis — a volumetric stellar nursery: emission gas, dark pillars and newborn stars under a drifting camera.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 cam = 0.08 * p_drift * lc(1.0, 0.0);
  vec3 col = vec3(0.0); float trans = 1.0;
  int L = 5 + int(8.0 * p_quality);
  for (int i = 0; i < 13; i++) {
    if (i >= L || trans < 0.03) break;
    float z = float(i) / float(L);               // 0 = near, 1 = far
    float par = mix(1.0, 0.25, z);
    vec2 q = (uv + cam * par) * p_scale * mix(1.6, 0.9, z) + float(i) * 1.37;
    // far layers need fewer octaves: they are smaller on screen and mostly hidden by dust
    float n = lfbm(q * 1.3, z < 0.5 ? 5 : 3, 1.0, 0.18 + 0.1 * p_turbulence);
    float w = lfbm(q * 0.6 + 7.0, z < 0.5 ? 3 : 2, 1.0, 0.2);
    float dens = smoothstep(0.0, 0.6, n + w * 0.6 + p_density - 0.55);
    // pillars: dark, dense columns rising from the bottom in the near layers
    float pil = 0.0;
    float pilAmt = p_pillars * (1.0 - z);
    if (pilAmt > 0.01 && uv.y < 0.55) {
      pil = smoothstep(0.15, 0.55, -uv.y * 0.9 + 0.35 * lfbm(vec2(q.x * 2.0, q.y * 0.4), 3, 1.0, 0.15)) * smoothstep(0.55, 0.9, 0.5 + 0.5 * sin(q.x * 3.0 + w * 3.0)) * pilAmt;
    }
    // emission: H-alpha (a0) vs OIII (a2) by ionisation (distance from the hot core)
    float ion = sat(1.0 - length(uv - vec2(0.15, 0.12)) * 1.4 + n * 0.3);
    vec3 em = mix(u_a0, u_a2, ion * p_ionisation) * dens * (0.35 + 0.65 * sat(n + 0.4)) * 0.22 * p_glow * (11.0 / float(L + 1) * 0.9);
    col += em * trans;
    trans *= 1.0 - sat(dens * 0.12 * p_dust + pil * 0.6);
    // rim lighting on pillars
    col += mix(u_a1, u_ink, 0.4) * pil * (1.0 - pil) * 1.2 * trans * ion;
  }
  // newborn stars (embedded, with spikes)
  vec3 st = Q_stars2(uv + cam * 0.5, p_stars, p_spikes) * 1.4;
  col += st * (0.3 + 0.7 * trans);
  // the central cluster
  float dc = length(uv - vec2(0.15, 0.12));
  col += mix(u_ink, u_a2, 0.3) * exp(-dc * 30.0) * 0.8 * p_glow;
  col = aces(col * 1.3);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/orbitals.glsl:
// Orbitals — hydrogen probability clouds rendered volumetrically; a superposition sloshes at the transition frequency.
float OR_fact(int n) { float f = 1.0; for (int k = 2; k < 10; k++) { if (k > n) break; f *= float(k); } return f; }
// Generalised Laguerre L_k^a(x) by recurrence.
float OR_lag(int k, float a, float x) {
  float l0 = 1.0, l1 = 1.0 + a - x; if (k == 0) return l0; float lk = l1;
  for (int i = 1; i < 6; i++) { if (i >= k) break; float fi = float(i); float l2 = ((2.0 * fi + 1.0 + a - x) * l1 - (fi + a) * l0) / (fi + 1.0); l0 = l1; l1 = l2; lk = l2; }
  return lk;
}
float OR_R(int n, int l, float r) {
  float rho = 2.0 * r / float(n);
  return pow(rho, float(l)) * exp(-rho * 0.5) * OR_lag(n - l - 1, float(2 * l + 1), rho);
}
// Real spherical harmonics (unnormalised shape) up to l = 3.
float OR_Y(int l, int m, vec3 d) {
  float x = d.x, y = d.y, z = d.z;
  if (l == 0) return 0.5;
  if (l == 1) return m == 0 ? z : (m > 0 ? x : y);
  if (l == 2) { if (m == 0) return 3.0 * z * z - 1.0; if (m == 1) return x * z * 2.0; if (m == -1) return y * z * 2.0; if (m == 2) return x * x - y * y; return 2.0 * x * y; }
  if (m == 0) return z * (5.0 * z * z - 3.0); if (m == 1) return x * (5.0 * z * z - 1.0); if (m == -1) return y * (5.0 * z * z - 1.0);
  if (m == 2) return z * (x * x - y * y) * 3.0; if (m == -2) return 6.0 * x * y * z; if (m == 3) return x * (x * x - 3.0 * y * y); return y * (3.0 * x * x - y * y);
}
float OR_psi(int n, int l, int m, vec3 p) { float r = length(p); return OR_R(n, l, r) * OR_Y(l, m, p / max(r, 1e-4)); }
vec4 motif(vec2 uv, vec2 fc) {
  int n = p_n, l = min(p_l, n - 1), m = clamp(p_m, -l, l);
  float ang = TAU * u_p * float(p_spin);
  vec3 ro = vec3(sin(ang), 0.35 * p_elevation, cos(ang)) * 3.0;
  vec3 fw = normalize(-ro), rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw)), up = cross(fw, rt);
  vec3 rd = normalize(fw * 2.2 + uv.x * rt + uv.y * up);
  // orbital extent in Bohr radii: ~2.3 for 1s up to ~33 for n = 4, so every state fills the frame
  float scale = (2.3 + 2.5 * float(n) * (float(n) - 0.5)) / p_size;     // orbital extent in Bohr radii
  float T = 1.4;
  vec3 col = vec3(0.0); float acc = 0.0;
  int steps = 40 + int(60.0 * p_quality);
  float ds = 2.0 * T / float(steps);
  float jitter = h21(fc) * ds;
  // superposition partner: 1s, or the next lower state, beating at the transition frequency
  float beat = TAU * u_p * float(p_beat);
  float rmax = 0.0; for (int k = 1; k <= 16; k++) rmax = max(rmax, abs(OR_R(n, l, float(k) * float(n * n) * 0.18)));
  float nrm = 1.0 / max(rmax, 1e-4);
  for (int i = 0; i < 100; i++) {
    if (i >= steps) break;
    float t = 3.0 - T + float(i) * ds + jitter;
    vec3 p = ro + rd * t;
    vec3 q = p.xzy * scale;                      // z up
    float a = OR_psi(n, l, m, q) * nrm;
    float b = p_superpose > 0.0 ? OR_psi(1, 0, 0, q * 0.6) * 1.2 : 0.0;
    float re = a + p_superpose * b * cos(beat), im = p_superpose * b * sin(beat);
    // low shells occupy less of each ray, so lift them to a comparable exposure
    float dens = (re * re + im * im) * p_density * 0.9 * (0.69 + 5.0 / float(n * n));
    float sgn = re;
    vec3 c = sgn >= 0.0 ? u_a0 : u_a1;
    if (p_colour == COLOUR_PHASE) { float ph = atan(im, re) / TAU + 0.5; c = mix(mix(u_a0, u_a1, sat(ph * 2.0)), u_a2, sat(ph * 2.0 - 1.0)); }
    col += c * dens * ds * (1.0 - acc) * (1.0 - 0.7 * p_dots);
    // Monte-Carlo electron cloud: world-locked sample points, probability proportional to density
    if (p_dots > 0.0) { vec3 cell = floor(q * 1.6); vec3 hq = h33(cell); float dd = length(fract(q * 1.6) - hq); col += mix(c, u_ink, 0.4) * step(hq.x * 3.0, dens) * (1.0 - smoothstep(0.08, 0.14, dd)) * p_dots * 0.6 * (1.0 - acc); }
    acc += dens * ds * 0.25 * p_opacity;
    if (acc > 0.98) break;
  }
  // nucleus
  vec3 oc = -ro; float tc = dot(oc, rd); float dn = length(oc - rd * tc);
  col += u_ink * exp(-dn * dn * 9000.0) * 1.5 * (1.0 - acc * 0.7);
  col = aces(col * 1.4);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/post-bloom.glsl:
// Shared post pass: upsample pass 1, add a wide bloom and tone map. Uses p_bloom if the style defines it.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 t = fc / u_res; vec2 px = 1.0 / u_res;
  vec3 c = texture(u_buf0, t).rgb;
  vec3 bl = vec3(0.0); float wsum = 0.0;
  for (int i = 0; i < 16; i++) {
    float a = float(i) * 2.39996; float r = sqrt(float(i) + 0.5) * 3.2;
    vec2 o = vec2(cos(a), sin(a)) * r * px * (u_res.y / 360.0);
    vec3 s = texture(u_buf0, t + o).rgb; float w = 1.0 / (1.0 + r * 0.3);
    bl += max(s - 0.6, 0.0) * w; wsum += w;
  }
  bl /= wsum;
  vec3 col = aces((c + bl * 2.5 * p_bloom) * 1.05);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/pulsar.glsl:
// Pulsar — a spinning neutron star sweeps twin lighthouse beams through its magnetosphere and wind nebula.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 q = uv / p_scale;
  float rot_ = TAU * u_p * floor(safeCycles(2.0 * float(p_spin)) * 0.5);
  float tilt = p_obliquity * 0.9;
  vec3 col = vec3(0.0);
  float r = length(q);
  // wind nebula: torus + jets with wisps
  vec2 tq = q / vec2(1.0, 0.35);
  float torus = exp(-pow((length(tq) - 0.22) * 9.0, 2.0)) * (0.6 + 0.4 * lfbm(tq * 6.0, 4, 1.0, 0.3));
  float wisp = pow(0.5 + 0.5 * sin(length(tq) * 60.0 - TAU * u_p * float(p_spin) * 2.0), 6.0) * exp(-length(tq) * 5.0);
  float jet = exp(-q.x * q.x * 900.0) * exp(-abs(q.y) * 4.0) * (0.6 + 0.4 * lfbm(vec2(q.y * 10.0, 0.0), 3, float(p_spin), 0.3));
  col += (u_a2 * torus + u_a0 * wisp * 0.4 + u_a1 * jet * 0.6) * p_nebula;
  // magnetic dipole field lines, rotating with the star (projected)
  vec2 mq = rot(tilt * sin(rot_)) * q;
  float mr = length(mq), mth = atan(mq.x, mq.y);
  float s2 = sin(mth); s2 *= s2;
  float L = mr / max(s2, 1e-3);             // dipole: r = L sin^2(theta)
  float lines = 0.0;
  for (int i = 1; i <= 6; i++) {
    float Li = 0.06 * float(i) * p_field;
    lines += exp(-pow((L - Li) / (0.004 * float(i)), 2.0)) * exp(-mr * 2.0);
  }
  col += u_a2 * lines * 0.5;
  // beams: two cones along the magnetic axis, axis precesses around the spin axis
  float bx = sin(tilt) * cos(rot_);           // projected beam axis component toward viewer
  vec2 bdir = normalize(vec2(sin(tilt) * sin(rot_), cos(tilt)));
  float face = abs(bx);                       // beam pointing at the viewer
  for (int b = 0; b < 2; b++) {
    vec2 d = b == 0 ? bdir : -bdir;
    float al = dot(q, d);
    float pe = abs(dot(q, vec2(-d.y, d.x)));
    float cone = exp(-pe * pe / pow(0.006 + al * 0.12 * p_beamWidth, 2.0)) * step(0.0, al) * exp(-al * 1.5);
    col += mix(u_a0, u_ink, 0.4) * cone * 1.5;
  }
  // pulse: flash when a beam crosses the line of sight (limited)
  float pulseA = pow(face, 40.0 * (1.0 - p_beamWidth * 0.5) + 4.0);
  col += mix(u_ink, u_a0, 0.3) * flashAmt(pulseA) * p_pulse * exp(-r * 4.0) * 1.5;
  // neutron star
  col += u_ink * (1.0 - smoothstep(0.012, 0.014, r)) + u_a0 * glow2(r, 0.02) * 0.8;
  col += Q_stars2(uv, p_stars, 0.5) * 0.7;
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/quantum-foam.glsl:
// Quantum Foam — spacetime froth at the Planck scale: bubbles form and pop while virtual pairs flicker into existence.
vec4 motif(vec2 uv, vec2 fc) {
  vec2 p = uv * 7.0 * p_scale;
  // curvature noise warps the metric
  vec2 wq = p + p_curvature * 0.9 * vec2(lfbm(p * 0.35, 4, float(p_speed), 0.3), lfbm(p * 0.35 + 5.0, 4, float(p_speed), 0.3));
  vec3 v = lvoro(wq, 1.0, float(p_speed), 0.4);
  float edge = v.y - v.x;
  // each bubble has its own life cycle (loop-periodic): grow, shimmer, pop
  float life = fract(u_p * float(p_speed) + v.z * 7.0);
  float alive = smoothstep(0.0, 0.25, life) * (1.0 - smoothstep(0.8, 0.95, life));
  float popped = smoothstep(0.85, 1.0, life);
  // thin-film interference on the bubble wall
  float film = edge * 18.0 + v.z * 5.0 + life * 3.0;
  vec3 irid = 0.5 + 0.5 * cos(TAU * (vec3(0.0, 0.33, 0.67) + film * 0.15 * p_iridescence));
  vec3 filmC = u_a0 * irid.x + u_a1 * irid.y + u_a2 * irid.z;
  float wall = (1.0 - smoothstep(0.02 * p_wall, 0.02 * p_wall + 0.06, edge)) * alive;
  vec3 col = filmC * wall * 1.1 + u_ink * pow(wall, 6.0) * 0.4;
  // interior sheen
  col += filmC * 0.08 * (1.0 - v.x) * alive;
  // pop burst
  col += u_ink * exp(-v.x * 10.0) * popped * (1.0 - popped) * 4.0 * p_pops;
  // virtual particle pairs: appear, separate, annihilate (per cell of a finer grid)
  vec2 g = uv * 16.0 * p_pairDensity;
  vec2 n = floor(g);
  float pairs = 0.0;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
    vec2 c = n + vec2(float(i), float(j));
    vec3 h = h33(vec3(c, 9.0));
    if (h.z > p_pairs) continue;
    float t = fract(u_p * float(p_speed) * 2.0 + h.x);
    float sepa = sin(PI * t) * 0.35;
    vec2 dir = vec2(cos(TAU * h.y), sin(TAU * h.y));
    vec2 ctr = c + 0.5 + (h.xy - 0.5) * 0.5;
    vec2 e1 = ctr + dir * sepa, e2 = ctr - dir * sepa;
    float d1 = length(g - e1), d2 = length(g - e2);
    float br = sin(PI * t);
    pairs += (exp(-d1 * d1 * 80.0) + exp(-d2 * d2 * 80.0)) * br;
    // annihilation spark at the end of the life
    pairs += exp(-length(g - ctr) * 18.0) * smoothstep(0.9, 1.0, t) * 2.0;
  }
  col += mix(u_a1, u_ink, 0.3) * pairs * p_glow;
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/quasar-jet.glsl:
// Quasar Jet — a feeding supermassive black hole fires relativistic jets; knots race outward along a kinking helix.
vec4 motif(vec2 uv, vec2 fc) {
  float ang = p_angle * PI;
  vec2 ax = vec2(cos(ang), sin(ang)), nx = vec2(-ax.y, ax.x);
  vec2 q = uv / p_scale;
  float s = dot(q, ax), n = dot(q, nx);
  vec3 col = vec3(0.0);
  // host galaxy glow + dust lane
  float gal = exp(-length(q * vec2(1.0, 1.8)) * 3.0);
  float dust = 1.0 - 0.7 * p_dust * exp(-pow(dot(q, vec2(0.3, 1.0)) * 18.0, 2.0)) * (0.6 + 0.4 * lfbm(q * 8.0, 3, 1.0, 0.2));
  col += mix(u_a1, u_ink, 0.3) * gal * 0.5 * p_host * dust;
  // accretion disk seen at an angle (ellipse)
  vec2 dq = rot(ang) * q; dq.y /= 0.25;
  float dr = length(dq);
  float disk = exp(-pow((dr - 0.05) * 30.0, 2.0)) + exp(-dr * 40.0) * 2.0;
  col += Q_heat(0.8) * disk * p_core * dust;
  // jets (approaching: s>0, bright; receding: s<0, dimmed by Doppler)
  for (int j = 0; j < 2; j++) {
    float sg = j == 0 ? 1.0 : -1.0;
    float ss = s * sg;
    if (ss < 0.0) continue;
    float doppler = j == 0 ? 1.0 : 0.25 + 0.5 * (1.0 - p_beaming);
    float width = 0.006 + ss * 0.07 * p_opening;
    // helical kink: offset grows with distance, pattern travels outward
    float kink = p_kink * 0.05 * ss * sin(ss * 26.0 - TAU * u_p * float(p_speed) * 2.0);
    float kink2 = p_kink * 0.02 * ss * sin(ss * 61.0 - TAU * u_p * float(p_speed) * 5.0 + 1.0);
    float dn = n - kink - kink2;
    float core = exp(-dn * dn / (width * width));
    float sheath = exp(-dn * dn / (width * width * 9.0)) * 0.25;
    // knots: bright blobs moving outward, loop-periodic
    float kn = 0.0;
    for (int k = 0; k < 5; k++) {
      float x = fract(u_p * float(p_speed) + float(k) / 5.0 + h11(float(k) + sg));
      float pos = pow(x, 1.4) * 1.1;
      kn += exp(-pow((ss - pos) / (0.02 + pos * 0.04), 2.0)) * (1.0 - x) * 2.0;
    }
    float fall = exp(-ss * 1.4 / p_length);
    float turb = 0.7 + 0.3 * lfbm(vec2(ss * 12.0, dn * 40.0), 3, float(p_speed), 0.3);
    vec3 jc = mix(u_a2, u_a0, sat(ss * 1.5)) ;
    col += (jc * (core + sheath) * turb * fall + mix(u_ink, u_a2, 0.3) * kn * core * p_knots) * doppler * 1.6;
    // terminal lobe / hotspot
    float L = 0.9 * p_length;
    vec2 lp = vec2(ss - L, dn * 1.3);
    float lobe = exp(-dot(lp, lp) * 25.0) * (0.6 + 0.4 * lfbm(lp * 8.0, 4, 1.0, 0.3));
    col += u_a0 * lobe * p_lobes * doppler + u_ink * exp(-dot(lp, lp) * 900.0) * p_lobes * doppler;
  }
  col += Q_stars2(uv, p_stars, 0.6) * 0.8;
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/solar-corona.glsl:
// Solar Corona — a limb-darkened star boils with granulation while magnetic loops, prominences and streamers flow above it.
vec4 motif(vec2 uv, vec2 fc) {
  float R = 0.3 * p_size;
  vec2 c = vec2(p_offset * 0.3, -0.05);
  vec2 q = uv - c;
  float r = length(q);
  float a = atan(q.y, q.x);
  vec3 col = vec3(0.0);
  // corona streamers (radial)
  float str = pow(0.5 + 0.5 * lfbm(vec2(a * 3.0, 0.0) * 1.0 + 3.0, 4, 1.0, 0.3), 3.0);
  float corona = exp(-(r - R) * 5.0 / p_corona) * step(R, r) * (0.3 + str * 1.6);
  col += mix(u_a0, u_ink, 0.2) * corona * 0.5;
  // disc: granulation + limb darkening + sunspots
  if (r < R) {
    float mu = sqrt(1.0 - (r / R) * (r / R));
    vec2 sp = q / R;
    vec3 sph = vec3(sp, mu);
    sph.xz = rot(TAU * u_p * float(p_rotation) * 0.25) * sph.xz;
    vec2 tq = vec2(atan(sph.x, sph.z), sph.y);
    vec3 v = lvoro(tq * 16.0 * p_granulation, 0.9, float(p_boil), 0.25);
    float gran = 0.75 + 0.25 * smoothstep(0.0, 0.25, v.y - v.x) - 0.15 * v.x;
    float spots = smoothstep(0.55, 0.62, lfbm(tq * 2.0, 3, 1.0, 0.1)) * p_spots;
    float limb = pow(mu, 0.55);
    vec3 disc = mix(u_a0, mix(u_a1, u_ink, 0.5), limb) * limb * gran * (1.0 - 0.85 * spots) * 1.3;
    col = disc;
  }
  // coronal loops: magnetic arcs anchored on the limb, plasma flowing along them
  for (int i = 0; i < 8; i++) {
    if (i >= p_loops) break;
    float fi = float(i);
    vec3 h = h33(vec3(fi, 4.0, 2.0));
    float ang0 = (h.x - 0.5) * 2.2 + PI * 0.5 * (h.z < 0.5 ? 1.0 : -0.6) ;
    float span = 0.15 + 0.25 * h.y;
    vec2 f1 = c + vec2(cos(ang0 - span), sin(ang0 - span)) * R;
    vec2 f2 = c + vec2(cos(ang0 + span), sin(ang0 + span)) * R;
    vec2 mid = (f1 + f2) * 0.5;
    vec2 out_ = normalize(mid - c);
    float height = (0.08 + 0.18 * h.z) * p_loopHeight * (1.0 + 0.1 * lsin(1.0, h.x));
    // loop as an ellipse arc: parametrise by the chord coordinate
    vec2 chord = f2 - f1; float cl = length(chord); vec2 cd = chord / cl;
    vec2 lq = q + c - mid;
    float x = dot(lq, cd) / (cl * 0.5);
    float y = dot(lq, out_);
    float yArc = height * sqrt(max(1.0 - x * x, 0.0));
    float d = abs(y - yArc) * step(abs(x), 1.0) + step(1.0, abs(x)) * 1.0;
    float s = acos(clamp(x, -1.0, 1.0)) / PI;
    float flow = pulse(s, float(p_flow), h.y, 0.08) * 0.8 + 0.4;
    float above = step(R * 0.98, r);
    float lw = 0.004 * (0.6 + h.y);
    col += mix(u_a1, u_ink, flow * 0.4) * (line(d, lw) * flow * 1.2 + glow2(d, lw * 3.0) * 0.18 * p_glow) * above;
  }
  // prominence: a curtain of plasma on one limb
  float pa = PI * 0.12;
  vec2 pc = c + vec2(cos(pa), sin(pa)) * R;
  vec2 pq = rot(-pa) * (uv - pc);
  float prom = smoothstep(0.0, 0.01, pq.x) * exp(-pq.x * 14.0 / p_prominence) * exp(-pq.y * pq.y * 60.0) * pow(sat(lfbm(pq * vec2(8.0, 20.0), 5, 1.0, 0.3) + 0.5), 2.0);
  col += mix(u_a1, u_a0, 0.3) * prom * 1.6 * p_prominence;
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/supernova.glsl:
// Supernova — a star collapses and detonates; a Rayleigh-Taylor shock shell tears outward and cools into a remnant.
vec4 motif(vec2 uv, vec2 fc) {
  float ph = fract(u_p * safeCycles(float(p_cycles)) + 0.72);   // 0.0 = detonation (offset so the loop opens mid-remnant)
  vec2 q = uv / p_scale;
  float r = length(q);
  float a = atan(q.y, q.x);
  vec3 col = vec3(0.0);
  // progenitor: bright star that swells before collapse (ph near 1)
  float pre = smoothstep(0.55, 0.97, ph);
  float starR = mix(0.004, 0.02, pre);
  col += mix(u_ink, u_a1, 0.3) * exp(-r * r / (starR * starR)) * (0.6 + 1.6 * pre) * (1.0 - smoothstep(0.985, 1.0, ph));
  // shock radius (fast then slowing: Sedov-Taylor ~ t^0.4)
  float age = sat(ph / 0.9);
  float R = 0.62 * pow(age, 0.4) * p_size;
  float fade = 1.0 - smoothstep(0.55, 0.95, ph);
  // Rayleigh-Taylor fingers: noisy radius by angle (loop via ln2 on a circle in angle space)
  vec2 ac = vec2(cos(a), sin(a));
  float fing = lridge(ac * 2.2 * p_filaments + 3.0, 4, 1.0, 0.3);
  float rr = R * (1.0 - 0.18 * p_instability * fing);
  float shell = exp(-pow((r - rr) / (0.012 + 0.03 * age), 2.0));
  float limb = 1.0 / sqrt(max(1.0 - sat(r / max(rr, 1e-3)) * sat(r / max(rr, 1e-3)), 0.04));
  // filament texture inside the shell
  float fil = lfbm3(vec3(q * 7.0 * p_filaments, age * 2.0), 5, 1.0, 0.3);
  float inner = smoothstep(rr, rr * 0.2, r) * pow(sat(0.55 + fil), 2.0);
  float temp = 1.0 - age;
  vec3 hotC = mix(u_a0, u_ink, sat(temp * 1.5));
  vec3 coolC = mix(u_a2, u_a1, sat(fil + 0.5));
  vec3 ej = mix(coolC, hotC, sat(temp * 1.2));
  col += ej * inner * 1.3 * fade * p_ejecta;
  col += mix(u_a1, u_ink, sat(temp)) * shell * min(limb, 4.0) * 0.7 * fade;
  // detonation flash (limited under the photosensitive guard)
  float flash = exp(-ph * 60.0) + exp(-(1.0 - ph) * 400.0) * 0.0;
  col += mix(u_ink, u_a1, 0.2) * flashAmt(flash) * p_flash * (0.4 + 2.0 * exp(-r * 6.0));
  // light echoes: faint rings at larger radii
  for (int i = 1; i <= 3; i++) {
    float er = R * (1.4 + float(i) * 0.5);
    col += u_a2 * exp(-pow((r - er) * 60.0, 2.0)) * 0.12 * p_echoes * fade * (0.6 + 0.4 * lfbm(ac * 3.0 + float(i), 3, 1.0, 0.3));
  }
  // neutron star remnant
  col += u_a2 * exp(-r * r * 20000.0) * 2.0 * step(0.02, ph) * step(ph, 0.95);
  col += Q_stars2(uv, p_stars, 0.8) * 0.8;
  col = aces(col * 1.2);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/tokamak.glsl:
// Tokamak — a burning plasma torus confined by twisted field lines; D-shaped coils ring it as edge bursts flicker.
float TK_torus(vec3 p, float R, float r) { vec2 q = vec2(length(p.xz) - R, p.y / 1.3); return length(q) - r; }
vec4 motif(vec2 uv, vec2 fc) {
  float ang = 0.35 + p_orbit * 0.4 * lsin(1.0, 0.0);
  vec3 ro = vec3(sin(ang) * 3.0, 1.1 + 0.9 * p_elevation, cos(ang) * 3.0);
  vec3 fw = normalize(vec3(0.0, -0.1, 0.0) - ro), rt = normalize(cross(vec3(0.0, 1.0, 0.0), fw)), up = cross(fw, rt);
  vec3 rd = normalize(fw * 2.0 + uv.x * rt + uv.y * up);
  float R = 0.7, rp = 0.24;
  vec3 col = vec3(0.0); float trans = 1.0;
  float t = 0.4;
  float spin = TAU * u_p * float(p_flow);
  int steps = 40 + int(60.0 * p_quality);
  for (int i = 0; i < 100; i++) {
    if (i >= steps) break;
    vec3 p = ro + rd * t;
    float dt = TK_torus(p, R, rp);
    // coils (D-shaped rings at fixed toroidal angles) as solid occluders
    float phi = atan(p.z, p.x);
    float nc = max(float(p_coils), 1.0);
    float cphi = (floor(phi / TAU * nc + 0.5)) * TAU / nc;
    vec3 cp = vec3(cos(cphi), 0.0, sin(cphi));
    vec3 lp = vec3(dot(p, cp) - R, p.y, dot(p, vec3(-cp.z, 0.0, cp.x)));
    float coil = length(vec2(length(lp.xy / vec2(1.0, 1.35)) - rp * 1.75, lp.z)) - 0.009 + (p_coils == 0 ? 1e3 : 0.0);
    if (coil < 0.002) {
      vec3 n = normalize(vec3(lp.x, lp.y, 0.0) + 1e-4);
      float lit = 0.3 + 0.7 * sat(dot(n, normalize(-lp + vec3(0.0, 0.0, 0.0) - vec3(0.0, 0.3, 0.0))));
      col += (u_bg * 2.0 + u_ink * 0.12 * lit) * trans * p_coilLight + u_a0 * 0.15 * trans * p_coilLight;
      trans = 0.0; break;
    }
    if (dt < 0.0) {
      // plasma: dense core, twisted field lines (safety factor q), turbulence
      vec2 pq = vec2(length(p.xz) - R, p.y / 1.3);
      float rr = length(pq) / rp;
      float th = atan(pq.y, pq.x);
      float qf = 1.0 + 3.0 * p_twist;
      float lines = pow(0.5 + 0.5 * sin(float(p_fieldLines) * (th - phi * qf) + spin * 3.0), 8.0);
      float core = exp(-rr * rr * 2.2);
      float turb = 0.6 + 0.4 * ln3(p * 4.0, float(p_flow), 0.4);
      float elm = pow(sat(sin(phi * 5.0 + th * 2.0 - spin * 4.0)), 20.0) * p_bursts * smoothstep(0.6, 1.0, rr);
      vec3 em = mix(u_a1, u_a0, core) * (0.25 + core * 1.4) * turb + mix(u_a0, u_ink, 0.3) * lines * (0.3 + 0.7 * (1.0 - rr)) * 0.8 + u_ink * elm * 1.4;
      float dens = (0.15 + core * 0.6 + lines * 0.25 + elm * 0.4) * p_density;
      col += em * dens * 0.1167 * trans;
      trans *= 1.0 - dens * 0.0583;
      t += 0.02;
    } else {
      t += max(min(dt, coil) * 0.8, 0.01);
    }
    if (t > 7.0 || trans < 0.02) break;
  }
  // vessel wall glow
  col += u_a0 * 0.03 * (1.0 - trans) * p_glow;
  col = aces(col * 1.4 * p_glow);
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/wavefunction.glsl:
// Wavefunction — a 2D quantum harmonic oscillator: superposed eigenstates slosh through the well; density as light, phase as colour.
float WF_herm(int n, float x) {
  float h0 = 1.0, h1 = 2.0 * x;
  if (n == 0) return h0;
  float hn = h1;
  for (int k = 1; k < 8; k++) { if (k >= n) break; float h2 = 2.0 * x * h1 - 2.0 * float(k) * h0; h0 = h1; h1 = h2; hn = h2; }
  return hn;
}
float WF_phi(int n, float x) {
  float f = 1.0; for (int k = 2; k < 9; k++) { if (k > n) break; f *= float(k); }
  float norm = 1.0 / sqrt(pow(2.0, float(n)) * f) * 0.7511;
  return norm * WF_herm(n, x) * exp(-0.5 * x * x);
}
vec4 motif(vec2 uv, vec2 fc) {
  vec2 x = uv / (0.09 * p_width);
  vec2 psi = vec2(0.0);   // complex amplitude
  int S = p_states;
  for (int i = 0; i < 8; i++) {
    if (i >= S) break;
    vec3 h = h33(vec3(float(i), 3.0, 1.0));
    int nx = int(h.x * float(p_excitation + 1)), ny = int(h.y * float(p_excitation + 1));
    float amp = 1.0 / sqrt(float(S)) * (0.6 + 0.8 * h.z);
    float E = float(nx + ny + 1);
    float ph = -E * TAU * u_p * float(p_speed) + h.z * TAU;
    float v = WF_phi(nx, x.x) * WF_phi(ny, x.y) * amp;
    psi += v * vec2(cos(ph), sin(ph));
  }
  float rho = dot(psi, psi);
  float arg = atan(psi.y, psi.x) / TAU + 0.5;
  float I = 1.0 - exp(-rho * 40.0 * p_contrast);
  // phase colour cycles through the three accents
  vec3 pc = arg < 1.0 / 3.0 ? mix(u_a0, u_a1, arg * 3.0) : arg < 2.0 / 3.0 ? mix(u_a1, u_a2, arg * 3.0 - 1.0) : mix(u_a2, u_a0, arg * 3.0 - 2.0);
  vec3 col;
  if (p_view == VIEW_DENSITY) col = mix(u_a2 * 0.3, mix(u_a0, u_ink, I), I) * I;
  else if (p_view == VIEW_REAL) { float re = psi.x * 8.0 * p_contrast; col = (re > 0.0 ? u_a0 : u_a1) * sat(abs(re)); }
  else col = pc * I * 1.3 + u_ink * pow(I, 6.0) * 0.4;
  // contours of |psi|^2
  if (p_contours > 0.0) {
    float c = fract(rho * 60.0 * p_contrast);
    float wline = fwidth(rho * 60.0 * p_contrast);
    col += u_ink * p_contours * 0.5 * (1.0 - smoothstep(0.0, wline * 1.5, min(c, 1.0 - c))) * sat(rho * 30.0);
  }
  // potential well rings
  if (p_grid) { float pr = length(uv) / (0.09 * p_width); float gr = abs(fract(pr * 0.5) - 0.5); col += u_ink * 0.07 * (1.0 - smoothstep(0.0, 0.03, gr)) * exp(-pr * 0.12); }
  return vec4(col, max(max(col.r, col.g), col.b));
}

files.styles/wormhole.glsl:
// Wormhole — an Einstein-Rosen throat: one sky lensed around the rim, another universe glowing through it.
vec3 WH_sky(vec3 d, float which) {
  vec3 s = Q_stars(d, p_stars) * 1.2;
  float neb = lfbm3(d * 2.5 + which * 11.0, 4, 1.0, 0.25) * 0.5 + 0.5;
  vec3 tint = which > 0.5 ? mix(u_a1, u_a2, neb) : mix(u_a0 * 0.4, u_a2 * 0.5, neb);
  return s + tint * pow(neb, 3.0) * (which > 0.5 ? 1.2 : 0.35) * p_nebula;
}
vec4 motif(vec2 uv, vec2 fc) {
  float R = 0.27 * p_size;
  float r = length(uv);
  float a = atan(uv.y, uv.x);
  float spin = TAU * u_p * float(p_spin);
  vec3 col;
  if (p_mode == MODE_TRANSIT) {
    // flying through the throat: log-polar tunnel with streaming walls
    float z = log(max(r, 1e-3)) * 1.6;
    vec2 tq = vec2(a / TAU * float(p_arms) + z * p_twist * 0.3, z - u_p * float(p_spin) * 2.0);
    float walls = Q_tnoise(vec2(tq.x / float(p_arms), tq.y * 0.5), vec2(1.3, 1.1), 5);
    float streaks = pow(0.5 + 0.5 * sin(TAU * (tq.x * 3.0 + walls)), 8.0);
    vec3 wc = mix(u_a0, u_a1, 0.5 + 0.5 * walls) * (0.4 + walls) + u_ink * streaks * 0.6;
    float depth = smoothstep(0.0, 0.5, r);
    col = wc * depth * 1.4 + mix(u_a2, u_ink, 0.5) * exp(-r * 18.0) * 2.0;
  } else {
    vec3 d;
    float which = 0.0;
    if (r > R) {
      // outside: deflection ~ R^2/r (Einstein ring at r = R)
      float defl = p_lensing * R * R / r * 2.2;
      float rr = r - defl;
      vec2 duv = (rr < 0.0 ? -1.0 : 1.0) * normalize(uv) * abs(rr);
      d = normalize(vec3(duv * 1.4, -1.0));
    } else {
      // inside: the other universe, inverted and twisted
      which = 1.0;
      float ri = R * R / max(r, 1e-4);
      float tw = p_twist * 3.0 * (1.0 - r / R) + spin;
      vec2 duv = rot(tw) * normalize(uv) * ri;
      d = normalize(vec3(duv * 0.6, -1.0));
    }
    d.xz = rot(0.3 * lsin(1.0, 0.0)) * d.xz;
    col = WH_sky(d, which);
    // photon ring at the throat
    float ring = exp(-pow((r - R) / (0.006 + 0.01 * p_ring), 2.0));
    float swirl = 0.5 + 0.5 * sin(a * float(p_arms) + log(max(r, 1e-3)) * 10.0 - spin * 2.0);
    col += mix(u_a1, u_ink, 0.4) * ring * (1.2 + swirl) * p_ring;
    col += u_a0 * glow2(r - R, 0.03) * 0.25 * p_ring * swirl;
  }
  col = aces(col * 1.1);
  return vec4(col, max(max(col.r, col.g), col.b));
}
